using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using McpStdioServer;

var builder = Host.CreateApplicationBuilder(args);

// Redirect all logging to stderr so it never contaminates the
// JSON-RPC messages flowing over stdout.
builder.Logging.ClearProviders();
builder.Logging.AddConsole(opts => opts.LogToStandardErrorThreshold = LogLevel.Trace);

builder.Services.AddHttpClient("ExternalApi", client =>
{
    client.BaseAddress = new Uri("https://api.example.com/");
});

builder.Services
    .AddMcpServer(options =>
    {
        options.ServerInfo = new() { Name = "McpStdioServer", Version = "1.0.0" };
    })
    .WithStdioServerTransport()
    .WithTools<ApiTools>()
    .WithPrompts<SummarizationPrompts>();

await builder.Build().RunAsync();

