using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpStdioServer;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool, Description("Fetches data from the external API for a given resource ID.")]
    public static async Task<string> FetchResource(
        IHttpClientFactory httpClientFactory,
        ILogger<ApiTools> logger,
        [Description("The resource identifier to look up")] string resourceId,
        CancellationToken cancellationToken)
    {
        logger.LogInformation("Fetching resource {ResourceId}", resourceId);

        using var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync($"resources/{resourceId}", cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        return json.ToString();
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpStdioServer;

[McpServerPromptType]
public sealed class SummarizationPrompts
{
    [McpServerPrompt, Description("Creates a prompt that asks the model to summarize the given text.")]
    public static GetPromptResult Summarize(
        [Description("The text to summarize")] string text,
        [Description("Maximum number of sentences in the summary (default: 3)")] int? maxSentences = 3)
    {
        return new GetPromptResult
        {
            Description = "Summarization prompt",
            Messages =
            [
                new PromptMessage
                {
                    Role = Role.User,
                    Content = new Content
                    {
                        Type = "text",
                        Text = $"""
                            Summarize the following text in at most {maxSentences ?? 3} sentences.
                            Be concise and capture the key points.

                            Text:
                            {text}
                            """
                    }
                }
            ]
        };
    }
}

